    model.addConstrs(quicksum(x[i, j] for j in range(1, n + 1) if i != j) == 1 for i in range(1, n + 1))
    model.addConstrs(quicksum(x[j, i] for j in range(1, n + 1) if i != j) == 1 for i in range(1, n + 1))
    model.addConstrs(u[i] - u[j] + n * x[i, j] <= n - 1 for i in range(1, n + 1) for j in range(1, n + 1) if i != j)
    model.addConstrs(x[i, j] + x[j, i] <= 1 for i in range(1, n + 1) for j in range(1, n + 1) if i < j)

    # Set objective
    model.setObjective(quicksum(dist[i, j] * x[i, j] for i in range(1, n + 1) for j in range(1, n + 1) if i != j), GRB.MAXIMIZE)

    # Optimize/solve the model
    model.optimize()

    # Return the optimized model
    return model
